package org.json;import java.util.*;public class JSONArray{final List<Object> v=new ArrayList<>();public JSONArray(){}public JSONArray(String s){}public int length(){return v.size();}public JSONArray put(Object o){v.add(o);return this;}public JSONObject getJSONObject(int i){return (JSONObject)v.get(i);}public JSONObject optJSONObject(int i){return v.get(i) instanceof JSONObject?(JSONObject)v.get(i):null;}}